// Generate synthetic arithmetic captcha images (PNG) + answer key, no external deps.
// Minimal PNG encoder using zlib. Draws 'a?b=?' text via 5x7 bitmap font.
import fs from 'node:fs'
import zlib from 'node:zlib'

// 5x7 font for digits, +, -, *, =, ?, x, space
const FONT = {
'0':['01110','10001','10011','10101','11001','10001','01110'],
'1':['00100','01100','00100','00100','00100','00100','01110'],
'2':['01110','10001','00001','00010','00100','01000','11111'],
'3':['11111','00010','00100','00010','00001','10001','01110'],
'4':['00010','00110','01010','10010','11111','00010','00010'],
'5':['11111','10000','11110','00001','00001','10001','01110'],
'6':['00110','01000','10000','11110','10001','10001','01110'],
'7':['11111','00001','00010','00100','01000','01000','01000'],
'8':['01110','10001','10001','01110','10001','10001','01110'],
'9':['01110','10001','10001','01111','00001','00010','01100'],
'+':['00000','00100','00100','11111','00100','00100','00000'],
'-':['00000','00000','00000','11111','00000','00000','00000'],
'*':['00000','10001','01010','00100','01010','10001','00000'],
'=':['00000','00000','11111','00000','11111','00000','00000'],
'?':['01110','10001','00001','00010','00100','00000','00100'],
'x':['00000','10001','01010','00100','01010','10001','00000'],
' ':['00000','00000','00000','00000','00000','00000','00000'],
}

function crc32(buf){let c=~0;for(let i=0;i<buf.length;i++){c^=buf[i];for(let k=0;k<8;k++)c=(c>>>1)^(0xEDB88320&-(c&1));}return ~c>>>0}
function chunk(type,data){const t=Buffer.from(type,'ascii');const len=Buffer.alloc(4);len.writeUInt32BE(data.length);const crc=Buffer.alloc(4);crc.writeUInt32BE(crc32(Buffer.concat([t,data])));return Buffer.concat([len,t,data,crc])}
function encodePNG(w,h,rgba){
  const sig=Buffer.from([137,80,78,71,13,10,26,10]);
  const ihdr=Buffer.alloc(13);ihdr.writeUInt32BE(w,0);ihdr.writeUInt32BE(h,4);ihdr[8]=8;ihdr[9]=6;ihdr[10]=0;ihdr[11]=0;ihdr[12]=0;
  const raw=Buffer.alloc((w*4+1)*h);
  for(let y=0;y<h;y++){raw[y*(w*4+1)]=0;rgba.copy(raw,y*(w*4+1)+1,y*w*4,(y+1)*w*4)}
  const idat=zlib.deflateSync(raw);
  return Buffer.concat([sig,chunk('IHDR',ihdr),chunk('IDAT',idat),chunk('IEND',Buffer.alloc(0))]);
}

function render(text, scale, noise){
  const padX=8, padY=8;
  const cw=6, ch=8; // cell incl spacing
  const w=(text.length*cw+padX*2)*scale;
  const h=(7+padY*2)*scale;
  const img=Buffer.alloc(w*h*4,255);
  // background light
  for(let i=0;i<w*h*4;i+=4){img[i]=250;img[i+1]=250;img[i+2]=252;img[i+3]=255}
  const set=(x,y,r,g,b)=>{if(x<0||y<0||x>=w||y>=h)return;const o=(y*w+x)*4;img[o]=r;img[o+1]=g;img[o+2]=b;img[o+3]=255}
  let ox=padX;
  for(const ch of text){
    const glyph=FONT[ch]||FONT['?'];
    for(let gy=0;gy<7;gy++)for(let gx=0;gx<5;gx++){
      if(glyph[gy][gx]==='1'){
        for(let sy=0;sy<scale;sy++)for(let sx=0;sx<scale;sx++){
          const px=(ox+gx)*scale+sx, py=(padY+gy)*scale+sy;
          set(px,py,20,60,180); // blue-ish text
        }
      }
    }
    ox+=cw;
  }
  // noise lines/dots
  for(let n=0;n<noise;n++){
    const x=Math.floor(Math.random()*w), y=Math.floor(Math.random()*h);
    for(let t=0;t<6;t++){set(x+t,y+Math.floor(Math.sin(t)*2),150,150,160)}
  }
  return {buf:encodePNG(w,h,img),w,h}
}

const N = +(process.argv[2]||30)
const outdir = process.argv[3] || '.'
const key = []
for(let i=0;i<N;i++){
  const op = ['+','-','*'][Math.floor(Math.random()*3)]
  let a=Math.floor(Math.random()*9)+1, b=Math.floor(Math.random()*9)+1
  if(op==='-'&&b>a){[a,b]=[b,a]}
  const text = `${a}${op==='*'?'x':op}${b}?=`
  const ans = op==='+'?a+b:op==='-'?a-b:a*b
  const {buf,w,h}=render(text,2,20)
  fs.writeFileSync(`${outdir}/c${i}.png`,buf)
  key.push({file:`c${i}.png`,text,answer:String(ans),a,b,op,w,h})
}
fs.writeFileSync(`${outdir}/key.json`,JSON.stringify(key,null,2))
console.log('generated',N,'captchas in',outdir)

