      if(!res.ok){lastErr='HTTP'+res.status;continue}
      const data=await res.json()
      const raw=(data?.choices?.[0]?.message?.content??'').trim()
      return {raw, ans:normalize(raw)}
    }catch(e){lastErr=e.message}
  }
  return {raw:'ERR:'+lastErr,ans:'ERR'}
}

