import fs from 'node:fs'
import zlib from 'node:zlib'
// Decode PNG (RGBA, no filter optimizations; our gen uses filter 0) and re-encode 2x nearest-neighbor
function decodePNG(buf){
  let p=8; let w=0,h=0; let idat=[];
  while(p<buf.length){const len=buf.readUInt32BE(p);const type=buf.toString('ascii',p+4,p+8);const data=buf.subarray(p+8,p+8+len);
    if(type==='IHDR'){w=data.readUInt32BE(0);h=data.readUInt32BE(4)}
    else if(type==='IDAT'){idat.push(data)}
    p+=12+len;}
  const raw=zlib.inflateSync(Buffer.concat(idat));
  const stride=w*4+1; const rgba=Buffer.alloc(w*h*4);
  for(let y=0;y<h;y++){const f=raw[y*stride]; if(f!==0) throw new Error('filter '+f+' unsupported');
    for(let x=0;x<w*4;x++) rgba[y*w*4+x]=raw[y*stride+1+x];}
  return {w,h,rgba}
}
function crc32(b){let c=~0;for(let i=0;i<b.length;i++){c^=b[i];for(let k=0;k<8;k++)c=(c>>>1)^(0xEDB88320&-(c&1));}return ~c>>>0}
function chunk(t,d){const ty=Buffer.from(t,'ascii');const l=Buffer.alloc(4);l.writeUInt32BE(d.length);const cr=Buffer.alloc(4);cr.writeUInt32BE(crc32(Buffer.concat([ty,d])));return Buffer.concat([l,ty,d,cr])}
function encodePNG(w,h,rgba){const sig=Buffer.from([137,80,78,71,13,10,26,10]);const ih=Buffer.alloc(13);ih.writeUInt32BE(w,0);ih.writeUInt32BE(h,4);ih[8]=8;ih[9]=6;
  const raw=Buffer.alloc((w*4+1)*h);for(let y=0;y<h;y++){raw[y*(w*4+1)]=0;rgba.copy(raw,y*(w*4+1)+1,y*w*4,(y+1)*w*4)}
  return Buffer.concat([sig,chunk('IHDR',ih),chunk('IDAT',zlib.deflateSync(raw)),chunk('IEND',Buffer.alloc(0))])}

export function upscale(src,dst,factor=2){
  const {w,h,rgba}=decodePNG(fs.readFileSync(src))
  const W=w*factor,H=h*factor,out=Buffer.alloc(W*H*4)
  for(let y=0;y<H;y++)for(let x=0;x<W;x++){const sx=Math.floor(x/factor),sy=Math.floor(y/factor);const so=(sy*w+sx)*4,do=(y*W+x)*4;
    out[do]=rgba[so];out[do+1]=rgba[so+1];out[do+2]=rgba[so+2];out[do+3]=255}
  fs.writeFileSync(dst,encodePNG(W,H,out))
  return {W,H}
}

